 "content": "from collections import Counter, deque


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            shape = frozenset((y-r0, x-c0) for y,x in cells)
            comps.append({'color': color, 'cells': cells, 'box': (r0,r1,c0,c1), 'shape': shape})
    return comps


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    # The large, thin right-angle component is the spatial frame.
    frames = []
    for obj in comps:
        r0,r1,c0,c1 = obj['box']
        bh, bw = r1-r0+1, c1-c0+1
        cells = set(obj['cells'])
        if len(cells) < 6 or bh < 3 or bw < 3:
            continue
        # A frame consists of two perpendicular arms meeting at a corner.
        for corner in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
            y0,x0 = corner
            row_arm = {(y0,x) for x in range(c0,c1+1)}
            col_arm = {(y,x0) for y in range(r0,r1+1)}
            if row_arm | col_arm <= cells and len(cells) <= len(row_arm | col_arm) + max(bh,bw):
                frames.append(obj)
                break
    if not frames:
        return [row[:] for row in grid]
    frame = max(frames, key=lambda o: len(o['cells']))
    r0,r1,c0,c1 = frame['box']
    def inside(obj):
        return all(r0 <= r <= r1 and c0 <= c <= c1 for r,c in obj['cells'])
    inside_by_shape = {}
    outside_by_shape = {}
    for obj in comps:
        if obj is frame:
            continue
        target = inside_by_shape if inside(obj) else outside_by_shape
        target.setdefault(obj['shape'], []).append(obj)
    out = [row[:] for row in grid]
    for shape, outs in outside_by_shape.items():
        if shape in inside_by_shape:
            for obj in outs:
                for r,c in obj['cells']:
                    out[r][c] = frame['color']
    return out


